DO $$
BEGIN
    IF to_regclass('quality.quality_actions') IS NOT NULL AND to_regclass('quality.non_conformances') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('quality.quality_actions') AND c.contype = 'f' AND a.attname = 'non_conformance_id'
    ) THEN
        ALTER TABLE quality.quality_actions ADD CONSTRAINT fk_quality_actions_non_conformance_id FOREIGN KEY (non_conformance_id) REFERENCES quality.non_conformances (id) NOT VALID;
        BEGIN
            ALTER TABLE quality.quality_actions VALIDATE CONSTRAINT fk_quality_actions_non_conformance_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_quality_actions_non_conformance_id left NOT VALID: stored rows of quality.quality_actions reference missing rows';
        END;
    END IF;
END $$;

